INSERT INTO impacts (id, category, title, hidden_stat, explanation, why_invisible, video_asset_url, thumbnail_url, hope_story, hope_story_title, hope_story_image_url, sources, global_per_second_rate, counter_unit, counter_label, display_order, is_active, created_at, updated_at) VALUES
('00000000-0000-0000-0000-000000000001', 'DIGITAL_CARBON_FOOTPRINT', 'Digital/AI Carbon Footprint', '4.95 grams of CO2 per email', 'Streaming 4K video for an hour generates more emissions than a 100-mile car trip. Training a single AI model emits as much CO2 as 5 cars in a lifetime.', 'Feels "virtual," has no physical trace', 'https://example.com/video/digital-carbon.mp4', 'https://example.com/thumbnail/digital-carbon.jpg', 'Google achieved 100% renewable energy for its global operations, and AI companies are now publishing their carbon footprints openly.', 'Renewable AI Revolution', 'https://example.com/images/renewable-ai.jpg', '[]', 0.0495, 'grams/sec', 'CO2 Emitted', 1, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000002', 'TIRE_BRAKE_DUST', 'Tire & Brake Dust', '3.5 million tons of particulate matter annually', 'EV owners assume zero emissions, but tire wear and brake dust from regenerative braking still produce fine particulates.', 'People assume EVs = zero pollution', 'https://example.com/video/tire-brake.mp4', 'https://example.com/thumbnail/tire-brake.jpg', 'Cities are implementing road surface sensors that optimize traffic flow, reducing particulate emissions by up to 30%.', 'Clean City Initiative', 'https://example.com/images/clean-cities.jpg', '[]', 3500000.0, 'tons/year', 'Particles Emitted', 2, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000003', 'FAST_FASHION_MICROPLASTICS', 'Fast Fashion Microplastics', '500,000 tons entering oceans annually', 'Synthetic fibers shed 700,000 microfibers per wash, invisible to the naked eye.', 'Clothes look clean and solid, not like waste', 'https://example.com/video/fashion.mp4', 'https://example.com/thumbnail/fashion.jpg', 'The Global Fashion Agenda reports 1,000+ brands have committed to ending single-use plastic packaging by 2025.', 'Fashion Revolution', 'https://example.com/images/fashion-revolution.jpg', '[]', 5000000000, 'fibers/day', 'Microplastics Shed', 3, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000004', 'LIGHT_POLLUTION', 'Light Pollution', '80% of the world population affected', 'Bright lights disrupt bird migration patterns, with 150 species now at risk of extinction from light disruption.', 'Seen as safety/aesthetic, not ecological harm', 'https://example.com/video/light.mp4', 'https://example.com/thumbnail/light.jpg', 'The International Dark-Sky Association has certified over 2,000 communities as "Dark Sky Friendly".', 'Dark Sky Movement', 'https://example.com/images/dark-sky.jpg', '[]', 0.5, 'sq km/min', 'Area Affected', 4, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000005', 'UNDERWATER_NOISE_POLLUTION', 'Underwater Noise Pollution', '1.5 billion marine animals affected', 'Shipping lanes and sonar operations disorient whales, with 40% of North Atlantic right whales failing to reproduce.', '"Silent" ocean is actually drowning in noise', 'https://example.com/video/underwater.mp4', 'https://example.com/thumbnail/underwater.jpg', 'The International Maritime Organization now requires quieter ship propellers for new vessels.', 'Quieter Oceans Initiative', 'https://example.com/images/quieter-oceans.jpg', '[]', 25, 'decibels/sec', 'Decibels Emitted', 5, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000006', 'FERTILIZER_RUNOFF', 'Synthetic Fertilizer Runoff', '435 aquatic dead zones globally', 'Excess nutrients cause algae blooms that deplete oxygen, creating dead zones where marine life cannot survive.', 'Farming seen as "natural"', 'https://example.com/video/fertilizer.mp4', 'https://example.com/thumbnail/fertilizer.jpg', 'Precision agriculture technologies have reduced fertilizer runoff by 45% in pilot regions.', 'Precision Agriculture', 'https://example.com/images/precision-ag.jpg', '[]', 2.5, 'tons/sec', 'Runoff Generated', 6, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000007', 'E_WASTE_RARE_EARTH_MINING', 'E-waste & Rare-Earth Mining', '53.6 million tons generated annually', 'Every smartphone upgrade drives toxic mining, with 800 phones worth of e-waste for every electric vehicle battery produced.', 'Old phones "sit in drawers," feels harmless', 'https://example.com/video/ewaste.mp4', 'https://example.com/thumbnail/ewaste.jpg', 'Circular economy models now recover 95% of rare earth elements from old electronics.', 'Circular Economy', 'https://example.com/images/circular-economy.jpg', '[]', 1.7, 'kg/sec', 'E-waste Generated', 7, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000008', 'HIDDEN_WATER_FOOTPRINT', 'Hidden Water Footprint', '2,700 liters per cotton t-shirt', 'A single burger requires 2,400 liters of water, but consumers rarely see water labels.', 'Water use not visible on products', 'https://example.com/video/water.mp4', 'https://example.com/thumbnail/water.jpg', 'Virtual water trade has reduced water stress in drought-prone regions by 30%.', 'Water Stewardship', 'https://example.com/images/water-stewardship.jpg', '[]', 0.08, 'liters/sec', 'Water Consumed', 8, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000009', 'PALM_OIL_SUPPLY_CHAINS', 'Palm Oil Supply Chains', 'Found in 50% of packaged goods', 'Hidden in 3,000+ products, driving deforestation of 2.5 million hectares annually.', 'Ingredient lists obscure it', 'https://example.com/video/palmoil.mp4', 'https://example.com/thumbnail/palmoil.jpg', 'Certified sustainable palm oil covers 20% of global production, with 30% annual growth in compliant plantations.', 'Sustainable Palm Oil', 'https://example.com/images/sustainable-palm.jpg', '[]', 79.4, 'hectares/sec', 'Deforestation Driven', 9, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000010', 'SPACE_DEBRIS_SATELLITE_POLLUTION', 'Space Debris & Satellite Pollution', '34,000 tracked objects >10cm', 'Mega-constellations create atmospheric metal pollution, with 1 satellite breakup every 1,000 days.', 'Feels irrelevant to daily life', 'https://example.com/video/space.mp4', 'https://example.com/thumbnail/space.jpg', 'The European Space Agency''s ClearSpace mission will remove 2-3 tons of debris by 2030.', 'Space Cleanup Mission', 'https://example.com/images/space-cleanup.jpg', '[]', 1.1, 'objects/sec', 'Debris Objects', 10, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000011', 'SOIL_EROSION_MONOCULTURE', 'Soil Erosion from Monoculture', '18.5 billion tons annually', 'Topsoil loss threatens future food security, with 33% of soil already degraded worldwide.', 'Invisible underground process', 'https://example.com/video/soil.mp4', 'https://example.com/thumbnail/soil.jpg', 'Regenerative farming practices have restored 50 million acres of degraded land since 2020.', 'Regenerative Agriculture', 'https://example.com/images/regenerative.jpg', '[]', 0.587, 'tons/sec', 'Soil Lost', 11, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('00000000-0000-0000-0000-000000000012', 'INDOOR_VOCS_FRAGRANCE_CHEMICALS', 'Indoor VOCs & Fragrance Chemicals', '10,000+ VOCs emitted daily', 'Air fresheners and cleaning products pollute indoor + outdoor air, affecting 2.5 billion people globally.', '"Clean smell" perceived as safe', 'https://example.com/video/voc.mp4', 'https://example.com/thumbnail/voc.jpg', 'Green building certifications now include VOC limits, reducing exposure by 80% in certified buildings.', 'Green Building Standards', 'https://example.com/images/green-building.jpg', '[]', 3.2, 'kgs/sec', 'VOCs Emitted', 12, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);